/// Whether the brackets ()[]{} in `s` are balanced and correctly nested.
pub fn is_balanced(s: Str) -> Bool {
  var stack: List[Str] = []
  for c in s.chars() {
    if c == "(" or c == "[" or c == "{" {
      stack = stack.push(c)
    } else if c == ")" or c == "]" or c == "}" {
      let want = match c {
        ")" => "(",
        "]" => "[",
        _ => "{",
      }
      match stack.last() {
        Some(top) => {
          if top != want {
            return false
          }
          stack = stack.remove_at(stack.len() - 1)
        },
        None => { return false },
      }
    }
  }
  return stack.is_empty()
}

